<template>
  <section :aria-label="`${title}SOFA六轴结果`">
    <p>{{ title }}固定24小时 {{ source.start_at }} 至 {{ source.end_at }}；资料可用截止 {{ source.as_of }}；医生当前回顾 {{ source.evaluation_at }}。</p>
    <p aria-label="SOFA已知观测小计">已知观测轴小计：{{ analysis.known_subtotal??'未知（无可明确计分观测轴）' }}；可明确观测 {{ analysis.observed_scored_domain_count }}/6轴。</p>
    <p aria-label="SOFA总分上下界">总分上下界：{{ analysis.lower_bound }} 至 {{ analysis.upper_bound }}。</p>
    <p aria-label="SOFA数值是否收敛">数值收敛：{{ analysis.exact_numeric_total??'尚未收敛' }}。</p>
    <p aria-label="SOFA完整协议总分">完整协议总分：{{ analysis.complete_total_score===null?'未满足，不能把小计或收敛值称为完整SOFA':`${analysis.complete_total_score}/24` }}；协议完整 {{ analysis.protocol_complete_domain_count }}/6轴。</p>
    <p>按原单位分别评分，kPa采用本地审核后的评分边界。</p>
    <el-table :data="analysis.domains" aria-label="SOFA六轴上下界与协议完整性"><el-table-column label="轴"><template #default="{row}">{{ sofaAxisLabels[row.axis] }}</template></el-table-column><el-table-column label="明确观测最高分"><template #default="{row}">{{ row.observed_max_score??'未知' }}</template></el-table-column><el-table-column label="上下界"><template #default="{row}">{{ row.lower_bound }} 至 {{ row.upper_bound }}</template></el-table-column><el-table-column label="数值收敛"><template #default="{row}">{{ row.exact_numeric_score??'未知' }}</template></el-table-column><el-table-column label="实际协议"><template #default="{row}">{{ row.protocol_complete?'完整':'未完整' }}</template></el-table-column><el-table-column label="核对"><template #default="{row}"><el-button @click="inspect(row.axis)">核对{{ sofaAxisLabels[row.axis] }}全部候选与证明</el-button></template></el-table-column></el-table>
    <details><summary>核对全部公开原量、原单位和不同时刻</summary><p>共 {{ facts.length }} 条公开原事实展示行，包含同原件的多个事实；仅界面分页，未裁剪完整投影。</p><el-table :data="visibleFacts" aria-label="SOFA完整公开原事实分页"><el-table-column prop="label" label="原事实" /><el-table-column prop="value" label="原值或原状态" /><el-table-column prop="unit" label="原单位" /><el-table-column prop="clock" label="真实原时刻" min-width="230" /><el-table-column prop="source_id" label="原技术来源" min-width="260" /></el-table><el-pagination v-if="facts.length>20" v-model:current-page="factPage" :page-size="20" :total="facts.length" layout="prev,pager,next" /></details>
    <p v-for="warning in noticeList(analysis.warnings)" :key="warning">{{ warning }}</p>
    <el-dialog v-model="open" :title="`${title}${sofaAxisLabels[axis]||''}全部原候选与精确证明`" width="min(1150px,96vw)">
      <template v-if="domain"><p>本轴全部 {{ domain.candidates.length }} 个候选。原记录未知、冲突和已排除状态分别保留。</p><p>未完整事项：{{ domain.coverage_issues.map(reasonLabel).join('、')||'本记录协议未发现缺项' }}。</p><p>决定本轴已证明下界的全部来源共 {{ domain.deciding_source_ids.length }} 项，保留并列证据。</p><ul aria-label="SOFA全部并列决定来源"><li v-for="id in witnessIds" :key="id" class="hash">{{ id }}</li></ul><el-pagination v-if="domain.deciding_source_ids.length>20" v-model:current-page="witnessPage" :page-size="20" :total="domain.deciding_source_ids.length" layout="prev,pager,next" />
        <article v-for="item in candidates" :key="item.candidate_id" :aria-label="`SOFA原候选 ${item.candidate_id}`"><p class="hash">{{ item.candidate_id }}；{{ item.status }}；明确观测分 {{ item.score??'未知' }}；候选界 {{ item.lower_bound }} 至 {{ item.upper_bound }}。</p><p>{{ item.reason_codes.map(reasonLabel).join('、') }}</p><p class="hash">全部原来源 {{ item.source_ids.join('、')||'无合格原测量，不填正常' }}</p><div v-for="(proof,index) in item.calculations" :key="index"><p v-if="proof.kind==='continuous_tier'">原连续给入档位证明：{{ proof.start_at }} 至 {{ proof.end_at }}；实际持续 {{ proof.duration_microseconds }} µs；本版最短时长 {{ proof.meets_minimum?'已满足':'未满足' }}；档位 {{ proof.tier }}。</p><p v-else>精确证明 {{ proof.kind }}：{{ proof.exact.numerator }}/{{ proof.exact.denominator }} {{ proof.exact.unit }}，保留有理数，不用显示舍入改变判读。</p><p class="hash">证明原来源 {{ proof.source_ids.join('、') }}</p></div></article>
        <el-pagination v-if="domain.candidates.length>20" v-model:current-page="candidatePage" :page-size="20" :total="domain.candidates.length" layout="prev,pager,next" />
      </template>
    </el-dialog>
  </section>
</template>
<script setup>
import { noticeText, noticeList } from "@/utils/noticeText.cjs";
import {computed,ref,watch} from "vue";
import {sofaAxisLabels} from "@/api/aiSofa";
const props=defineProps({source:{type:Object,required:true},analysis:{type:Object,required:true},title:{type:String,default:"本日"}});
const factPage=ref(1),axis=ref(""),open=ref(false),candidatePage=ref(1),witnessPage=ref(1),domain=computed(()=>props.analysis.domains.find(row=>row.axis===axis.value)),candidates=computed(()=>domain.value?.candidates.slice((candidatePage.value-1)*20,candidatePage.value*20)||[]),witnessIds=computed(()=>domain.value?.deciding_source_ids.slice((witnessPage.value-1)*20,witnessPage.value*20)||[]);
const reasons={missing_measurement:"缺少原测量",missing_branch:"缺少必要原分支",missing_pair:"缺少明确血气配对",missing_fio2:"缺少原FiO₂",missing_support:"缺少原支持状态",unsupported_unit:"原单位不在固定原生分支",unknown_quantity:"原数量未知",review_unknown:"用途判读未知",review_excluded:"原件已明确排除",unresolved_conflict:"原冲突未解决",inventory_incomplete:"原清单核查不完整",inventory_unknown:"原清单覆盖未知",protocol_incomplete:"实际记录协议不完整",protocol_unknown:"实际记录协议未知",outside_period:"不在固定本日范围",outside_scope:"不在已核适用范围",scope_unknown:"适用范围未核实",gcs_not_testable:"原GCS含NT",gcs_incomplete:"原GCS分项不完整",gcs_not_interpretable:"原GCS不可明确判读",gcs_anchor_invalid:"原GCS明确锚点已失效",gcs_confounding_unknown:"GCS干扰因素未排除",pair_not_confirmed:"原配对未确认",support_qualification_unknown:"本版呼吸支持定义未核实",qualifying_support_conflicts_with_original:"新支持声明与原未支持状态矛盾",continuous_iv_not_confirmed:"实际连续静脉给药未核实",continuity_not_confirmed:"原连续性未确认",weight_missing:"缺少明确原体重",weight_nonpositive:"原体重非正不能相除",weight_not_applicable:"原体重不适用于本段",mass_basis_not_confirmed:"原药物质量口径未核实",rate_scope_unknown:"原速率口径未知",stream_relation_unresolved:"同药物物理流关系未解决",overlapping_same_stream:"同物理流存在重叠冲突",unrepresented_drug_exposure:"存在未表示或未知药物暴露",duration_not_satisfied:"未证明达到本版持续要求",zero_rate_no_positive_exposure:"原零速率不触发正给入档",urine_gap:"整日原收集存在缺口",urine_overlap:"原尿量收集重叠",urine_crosses_period:"原尿量段跨越日界",urine_collection_incomplete:"原尿量收集不完整",urine_patient_total_unknown:"原患者总尿量声明未知",no_eligible_measurement:"无合格原测量",normal_imputation_forbidden:"缺测不得补正常"};
const reasonLabel=value=>reasons[value]||value,raw=value=>value===null||value===undefined?"未知":typeof value==="boolean"?(value?"true":"false"):String(value);
const facts=computed(()=>{const s=props.source,rows=[],add=(label,value,unit,clock,id)=>rows.push({label,value:raw(value),unit:unit||"",clock:clock||"",source_id:id}),quantity=(label,q,clock,id)=>add(label,q?.value===null?(q.value_kind==="qualitative"?"原定性结果（正文仅院内核对）":`未测（${q.absent_reason}）`):q?.value,q?.unit,clock,id);
 for(const item of s.lab_observations)quantity(item.analyte,item.quantity,item.collected_at_utc,item.source_id);
 for(const item of s.respiratory_observations){quantity("明确原PaO₂",item.pao2.quantity,item.pao2.collected_at_utc,item.pao2.source_id);if(item.fio2)quantity("明确原FiO₂",item.fio2.quantity,item.fio2.observed_at,item.fio2.source_id);add("本次采样本版呼吸支持核实",item.qualifying_respiratory_support,"",item.pao2.collected_at_utc,item.pair?.source_id||item.candidate_id);}
 for(const item of s.respiratory_support_observations){add("原呼吸支持模式",item.delivery_mode,"",item.start_at,item.source_id);add("原支持实际核实至",item.verified_until_at,"",item.ended_at,item.source_id);}
 for(const item of s.map_observations)quantity("原MAP",item.quantity,item.observed_at,item.source_id);
 for(const item of s.gcs_observations){for(const [key,value]of Object.entries(item.components))add({eye:"原睁眼E",verbal:"原言语V",motor:"原运动M"}[key],value.score??(value.absent_reason==="not_testable"?"NT（不能测试）":"未记录"),"",item.observed_at,item.source_id);add("原GCS可判读性",item.interpretable,"",item.observed_at,item.source_id);add("当前镇静干扰核实",item.sedation_confounding_status,"",item.observed_at,item.source_id);add("当前其他干扰核实",item.other_confounding_status,"",item.observed_at,item.source_id);}
 for(const group of s.vasoactive_groups)for(const item of group.intervals){const d=item.dose_input,prefix=item.verified_until_at<=s.start_at?"日前必要前缀":"原给入";add(`${prefix} ${group.drug_key}物理流关系`,group.relation,"",`${item.start_at} 至 ${item.verified_until_at}`,item.source_id);for(const key of ["rate","concentration","pump_rate"])if(d[key])quantity(`${prefix}${key}`,d[key],item.start_at,item.source_id);if(item.weight)quantity("本段明确原体重",item.weight.quantity,item.weight.observed_at,item.weight.source_id);add("原实际连续IV核实",item.continuous_iv,"",item.start_at,item.source_id);add("原速率口径",item.rate_scope,"",item.start_at,item.source_id);}
 for(const item of s.urine_intervals){add("原分段患者尿量",item.volume_ml??`未测（${item.absent_reason}）`,"mL",`${item.start_at} 至 ${item.end_at}`,item.source_id);add("原收集完整性",item.collection_completeness,"",item.end_at,item.source_id);add("原患者总量声明",item.patient_total,"",item.end_at,item.source_id);}
 return rows;});
const visibleFacts=computed(()=>facts.value.slice((factPage.value-1)*20,factPage.value*20));
function inspect(value){axis.value=value;candidatePage.value=witnessPage.value=1;open.value=true;}
watch([()=>props.source,()=>props.analysis],()=>{open.value=false;axis.value="";factPage.value=candidatePage.value=witnessPage.value=1;});
</script>
<style scoped>p{line-height:1.7}.hash{overflow-wrap:anywhere}article{padding:10px 0;border-bottom:1px solid #ddd}.el-pagination{margin:12px 0}</style>
